def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    n = int(input_data[0])
    a = []
    for i in range(n):
        a.append(int(input_data[i+1]))

    a.sort(reverse=True)

    found = False
    max_area = 0

    i = 0
    while i < n - 1:
        if a[i] == a[i+1]:
            found = True
            # Try to find a matching pair for the second side
            j = i + 2
            while j < n - 1:
                if a[j] == a[j+1]:
                    area = a[i] * a[j]
                    if area > max_area:
                        max_area = area
                    break
                j += 1
            i = j + 1
        else:
            i += 1

    if not found:
        max_area = 0

    # Re-check logic: the above nested loop might miss cases if we break early incorrectly.
    # Let's rewrite with a cleaner approach: collect all pairs first.

    pairs = []
    for i in range(n - 1):
        if a[i] == a[i+1]:
            pairs.append(a[i])
            i += 1  # skip next as it's used in pair

    if len(pairs) >= 2:
        pairs.sort(reverse=True)
        max_area = pairs[0] * pairs[1]
    else:
        max_area = 0

    print(max_area)

