import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    n = int(input_data[0])
    a = list(map(int, input_data[1:]))

    a.sort(reverse=True)

    candidates = []
    for i in range(n - 1):
        if a[i] == a[i + 1]:
            candidates.append(a[i])
            i += 1  # Skip the next one as it's already paired

    if len(candidates) < 2:
        print(0)
        return

    candidates.sort(reverse=True)

    if len(candidates) >= 2:
        print(candidates[0] * candidates[1])
    else:
        print(0)

if __name__ == "__main__":
    solve()
